    $('[data-action="home"]')?.addEventListener('click', renderCustomerHome); $('[data-action="login"]')?.addEventListener('click', () => openAuth('login')); $('[data-action="register"]')?.addEventListener('click', () => openAuth('register')); $('[data-action="logout"]')?.addEventListener('click', logout); $('[data-action="customer-bookings"]')?.addEventListener('click', showCustomerBookings);
