    root.innerHTML = `${customerHeader()}<main class="results-wrap"><div class="page-heading"><div><span class="eyebrow">جاري البحث</span><h1>نبحث عن أفضل الرحلات لك</h1><p class="muted">يتم الآن التحقق من الرحلات والمقاعد المتاحة.</p></div></div><section class="search-loading" aria-live="polite"><div class="loading-wheel"></div><div><b>جارٍ تحميل الرحلات…</b><p>لن يستغرق الأمر سوى لحظات.</p></div></section></main>`;
