    $('#clear-seat-selection')?.addEventListener('click', () => { state.selectedSeats = []; $$('[data-seat].selected').forEach((button) => { button.classList.remove('selected'); button.setAttribute('aria-pressed', 'false'); }); updateSeatSummary(); });
