  function updateSeatSummary() { saveBookingCheckpoint('seats'); const segment = state.trip.segment; const selected = state.selectedSeats; const chosenCount = $('#chosen-count'); const selectedCount = $('#selected-count'); const clearButton = $('#clear-seat-selection'); const chosenList = $('#chosen-seat-list'); if (chosenCount) chosenCount.textContent = selected.length ? `${selected.length} ${selected.length === 1 ? 'مقعد' : 'مقاعد'}` : 'لم تختر بعد'; if (selectedCount) selectedCount.textContent = String(selected.length); if (clearButton) clearButton.disabled = selected.length === 0;     if (chosenList) chosenList.innerHTML = selected.length ? selected.map((seat) => `<span class="chosen-seat-chip"><i class="bi bi-check2"></i>${esc(seatLabel(seat))}</span>`).join('') : '<span class="chosen-empty"><i class="bi bi-hand-index"></i> اختر مقعدًا من المخطط</span>'; $('#booking-total').textContent = money(Number(segment.amount) * selected.length, segment.currency_symbol); $('#continue-booking').disabled = selected.length === 0; }

