  async function showCustomerBookings() { clearBookingCheckpoint(); if (!isCustomerUser()) return openAuth('login'); try { const { items } = await api('bookings'); root.innerHTML = `${customerHeader()}<main class="results-wrap"><div class="page-heading"><div><h1>حجوزاتي</h1><p class="muted">تابع الحالة والتذاكر من حسابك.</p></div><button class="btn btn-outline btn-sm" data-action="home">العودة للرئيسية</button></div><div class="panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>رقم الحجز</th><th>الرحلة</th><th>التاريخ</th><th>الإجمالي</th><th>الحالة</th><th></th></tr></thead><tbody>${items.length?items.map((item)=>`<tr><td>${esc(item.booking_number)}</td><td>${esc(item.trip_number)}</td><td>${dateTime(item.departure_at)}</td><td>${money(item.total_amount,item.currency_symbol)}</td><td>${status(item.status)}</td><td><button class="btn ${['confirmed','completed'].includes(String(item.status)) ? 'btn-primary' : 'btn-outline'} btn-sm" data-booking-detail="${item.id}">${['confirmed','completed'].includes(String(item.status)) ? '<i class="bi bi-ticket-perforated"></i> عرض التذكرة' : 'عرض التفاصيل'}</button></td></tr>`).join(''):`<tr><td colspan="6">${empty('لا توجد حجوزات بعد.')}</td></tr>`}</tbody></table></div></div></main>`; window.RihlaPublicTemplate?.bindChrome?.(publicTemplateContext()); $('[data-action="home"]')?.addEventListener('click', renderCustomerHome); $$('[data-booking-detail]').forEach((button)=>button.addEventListener('click',()=>showCustomerBookingView(Number(button.dataset.bookingDetail)))); } catch(error){showToast(error.message,'error');} }
  async function showCustomerBookingView(id) { try { const { booking } = await api(`bookings/${id}`); if (['confirmed', 'completed'].includes(String(booking.status)) && Array.isArray(booking.tickets) && booking.tickets.length) { return renderBookingSuccess(booking, false); } return showBookingDetail(id); } catch (error) { showToast(error.message, 'error'); } }
  async function showBookingDetail(id) { try { const { booking } = await api(`bookings/${id}`); const whatsappLink = role === 'admin' ? whatsappBookingHref(booking) : ''; const canReview = String(booking.status) === 'completed' && !Number(booking.review_submitted) && booking.departure_at && new Date(String(booking.departure_at).replace(' ','T')) < new Date(); const canReceivePayment = role === 'admin' && state.user?.permissions?.includes('receive_payment') && !['paid','refunded'].includes(String(booking.payment_status)) && ['agent','company','bank_transfer'].includes(String(booking.payment_channel)); const segment=booking.segments?.[0]||{}; const routeName=`${segment.origin_name_ar||'مدينة الانطلاق'} ← ${segment.destination_name_ar||'الوجهة'}`; const stationMarkup = stationLocationMarkup(segment); const layer = modal(`<h2>تفاصيل الحجز ${esc(booking.booking_number)}</h2><p>${status(booking.status)}</p>${booking.cancellation_reason ? `<div class="booking-cancellation-reason"><i class="bi bi-exclamation-circle"></i><span><b>سبب الإلغاء أو الرفض:</b> ${esc(booking.cancellation_reason)}</span></div>` : ''}<div class="booking-detail-route"><strong>${esc(routeName)}</strong><span>${esc(booking.trip_number||'—')} · ${esc(booking.company_name||'—')}</span></div>${stationMarkup}${booking.customer_name?`<div class="booking-customer-card"><span>العميل الذي أجرى الحجز</span><strong>${esc(booking.customer_name)}</strong><small>${esc(booking.customer_email||'')}${booking.customer_phone?` · ${esc(booking.customer_phone)}`:''}</small></div>`:''}<div class="booking-detail-grid"><div><span>موعد المغادرة</span><strong>${dateTime(booking.departure_at)}</strong></div><div><span>موعد الوصول</span><strong>${dateTime(booking.arrival_at)}</strong></div><div><span>مصدر الحجز</span><strong>${esc(booking.source || '—')}</strong></div><div><span>حالة الدفع</span><strong>${esc(paymentLabel(booking.payment_status, booking.payment_channel))}</strong></div><div><span>طريقة الدفع</span><strong>${esc(({agent:'الدفع عند الوكيل',company:'الدفع في الشركة',bank_transfer:'تحويل بنكي'})[booking.payment_channel] || '—')}</strong></div>${booking.payment_bank_name ? `<div><span>حساب التحويل</span><strong>${esc(booking.payment_bank_name)} · ${esc(booking.payment_bank_account || '')}</strong></div>` : ''}<div><span>المهلة</span><strong>${dateTime(booking.held_until)}</strong></div><div><span>تاريخ الإنشاء</span><strong>${dateTime(booking.created_at)}</strong></div></div><div class="panel booking-passengers-panel" style="margin-top:14px"><div class="panel-head"><h3>بيانات المسافرين</h3><span class="status active">${booking.passengers.length} مسافر</span></div><div class="panel-body">${booking.passengers.map(p=>`<article class="booking-passenger-detail"><div class="booking-passenger-main"><strong>${esc(p.full_name_ar)}</strong><b>المقعد ${esc(p.seat_code)}</b></div><div class="booking-passenger-fields"><span>الجنس: ${esc(p.gender || '—')}</span><span>الهاتف: ${esc([p.phone_country_code,p.phone].filter(Boolean).join(' ') || '—')}</span><span>الجواز: ${esc(p.passport_number || '—')}</span><span>الميلاد: ${esc([p.birth_date,p.birth_place].filter(Boolean).join(' · ') || '—')}</span><span>إصدار الجواز: ${esc([p.passport_issue_date,p.passport_issue_place].filter(Boolean).join(' · ') || '—')}</span></div></article>`).join('') || empty('لا توجد بيانات مسافرين.') }<div class="summary-total">الإجمالي: ${money(booking.total_amount,booking.currency_symbol)}</div></div></div>${role === 'admin' && booking.status === 'pending' ? `<div class="modal-actions booking-admin-actions"><button class="btn btn-primary" type="button" data-detail-confirm="${booking.id}">تأكيد المسافر وإصدار التذاكر</button><button class="btn btn-danger-outline" type="button" data-detail-reject="${booking.id}">إلغاء الحجز</button>${whatsappLink ? `<a class="btn btn-whatsapp" href="${whatsappLink}" target="_blank" rel="noopener noreferrer"><i class="bi bi-whatsapp"></i> تواصل مع العميل واتساب</a>` : ''}${canReceivePayment ? `<button class="btn btn-outline" type="button" data-detail-payment="${booking.id}">تأكيد استلام الدفع</button>` : ''}</div>` : role === 'admin' && canReceivePayment ? `<div class="modal-actions booking-admin-actions">${whatsappLink ? `<a class="btn btn-whatsapp" href="${whatsappLink}" target="_blank" rel="noopener noreferrer"><i class="bi bi-whatsapp"></i> تواصل مع العميل واتساب</a>` : ''}<button class="btn btn-outline" type="button" data-detail-payment="${booking.id}">تأكيد استلام الدفع</button></div>` : role === 'admin' && whatsappLink ? `<div class="modal-actions booking-admin-actions"><a class="btn btn-whatsapp" href="${whatsappLink}" target="_blank" rel="noopener noreferrer"><i class="bi bi-whatsapp"></i> تواصل مع العميل واتساب</a></div>` : role === 'customer' && booking.status === 'pending' ? `<div class="modal-actions"><button class="btn btn-danger-outline" type="button" data-cancel-booking="${booking.id}">إلغاء الحجز</button></div>` : ''}${canReview?`<form class="review-form" data-review-form="${booking.id}"><h3>قيّم تجربتك</h3><p class="muted">تظهر التقييمات والتعليق للمخولين في لوحة التحكم، وتساعدنا على تحسين الخدمة.</p><div class="review-rating-grid"><div class="field"><label>تقييم الرحلة</label><select name="trip_rating" required><option value="">اختر من 1 إلى 5</option><option value="5">★★★★★ ممتاز</option><option value="4">★★★★ جيد جدًا</option><option value="3">★★★ جيد</option><option value="2">★★ يحتاج تحسين</option><option value="1">★ ضعيف</option></select></div><div class="field"><label>تقييم الشركة</label><select name="company_rating" required><option value="">اختر من 1 إلى 5</option><option value="5">★★★★★ ممتاز</option><option value="4">★★★★ جيد جدًا</option><option value="3">★★★ جيد</option><option value="2">★★ يحتاج تحسين</option><option value="1">★ ضعيف</option></select></div>${booking.agent_id ? `<div class="field"><label>تقييم الوكيل</label><select name="agent_rating" required><option value="">اختر من 1 إلى 5</option><option value="5">★★★★★ ممتاز</option><option value="4">★★★★ جيد جدًا</option><option value="3">★★★ جيد</option><option value="2">★★ يحتاج تحسين</option><option value="1">★ ضعيف</option></select></div>` : ''}</div><label class="checkbox-line"><input type="checkbox" name="recommendation" value="1" checked> أوصي بهذه الرحلة</label><div class="field"><label>تعليقك</label><textarea name="comment" maxlength="1000" rows="3" placeholder="اكتب تعليقك عن الرحلة والشركة والوكيل (اختياري)"></textarea></div><button class="btn btn-primary" type="submit">إرسال التقييم</button></form>`:''}`); $('[data-cancel-booking]', layer)?.addEventListener('click',()=>cancelBooking(id)); $('[data-detail-confirm]', layer)?.addEventListener('click',()=>confirmBooking(id,()=>{closeModal();loadDashboardPage(state.dashboardPage || 'bookings');})); $('[data-detail-payment]', layer)?.addEventListener('click',()=>receivePayment(id,()=>{closeModal();loadDashboardPage(state.dashboardPage || 'bookings');})); $('[data-detail-reject]', layer)?.addEventListener('click',()=>rejectBooking(id,()=>{closeModal();loadDashboardPage(state.dashboardPage || 'bookings');})); $('[data-review-form]',layer)?.addEventListener('submit',async event=>{event.preventDefault();try{const values=Object.fromEntries(new FormData(event.currentTarget));values.recommendation=event.currentTarget.querySelector('[name="recommendation"]').checked;await api(`bookings/${id}/review`,{method:'POST',body:JSON.stringify(values)});showToast('تم حفظ تقييمك.','success');event.currentTarget.innerHTML='<p class="status active">تم إرسال تقييمك بنجاح.</p>';}catch(error){showToast(error.message,'error');}}); } catch(error){showToast(error.message,'error');} }
  async function cancelBooking(id){ try{await api(`bookings/${id}/cancel`,{method:'POST',body:JSON.stringify({reason:'تم الإلغاء من حساب العميل.'})});closeModal();showToast('تم إلغاء الحجز.','success');showCustomerBookings();}catch(error){showToast(error.message,'error');} }

