  function bindSeparatedCreateForm(form,endpoint,host,reload,buildBody){
    form?.addEventListener('submit',async(event)=>{event.preventDefault();try{const body=buildBody?buildBody(form):Object.fromEntries(new FormData(form));await api(endpoint,{method:'POST',body:JSON.stringify(body)});operationContextCache=null;showToast('تم حفظ البيانات التشغيلية.','success');await reload(host);closeModal();}catch(error){showToast(error.message,'error');}});
  }
  function bindCompanyCreateWithMedia(form,host){
    form?.addEventListener('submit',async(event)=>{event.preventDefault();const submit=$('button[type="submit"]',form);if(submit)submit.disabled=true;try{const formData=new FormData(form);const logo=formData.get('company_logo');const cover=formData.get('company_cover');const galleryFiles=Array.from(form.querySelector('[name="company_gallery_files"]')?.files||[]).filter(file=>file.size>0).slice(0,6);const body=Object.fromEntries([...formData.entries()].filter(([key])=>!['company_logo','company_cover','company_gallery_files','location_query'].includes(key)));const {company}=await api('admin/companies',{method:'POST',body:JSON.stringify(body)});if(!company?.id)throw new Error('تم حفظ الشركة لكن تعذر تحديدها لرفع الوسائط.');const failed=[];for(const [slot,file,label] of [['logo',logo,'الشعار'],['cover',cover,'الصورة التعريفية']]){if(file instanceof File&&file.size>0){try{await uploadMedia(`admin/companies/${company.id}/media`,slot,file);}catch(error){failed.push(label);}}}for(const [index,file] of galleryFiles.entries()){try{await uploadMedia(`admin/companies/${company.id}/gallery`,'gallery',file,{image_order:index+1});}catch(error){failed.push(`صورة المعرض ${index+1}`);}}closeModal();if(failed.length){showToast(`تم إنشاء الشركة، لكن تعذر رفع ${failed.join(' و')}. يمكنك إعادة الرفع من بطاقة الشركة.`,'error');}else{showToast('تم إنشاء الشركة وحفظ الوسائط المختارة.','success');}dashboardCompanies(host);}catch(error){showToast(error.message,'error');}finally{if(submit)submit.disabled=false;}});
  }
