  function time12Field(prefix,label,value=''){const raw=String(value||'').slice(0,5);let [hour,minute]=(raw||'00:00').split(':').map(Number);const period=hour>=12?'pm':'am';hour=hour%12||12;const hours=Array.from({length:12},(_,i)=>i+1).map(h=>`<option value="${h}" ${h===hour?'selected':''}>${String(h).padStart(2,'0')}</option>`).join('');const minutes=Array.from({length:60},(_,i)=>`<option value="${String(i).padStart(2,'0')}" ${i===minute?'selected':''}>${String(i).padStart(2,'0')}</option>`).join('');return `<div class="field time12-field"><label>${label}</label><div class="time12-controls"><select name="${prefix}_hour" required aria-label="${label} — الساعة">${hours}</select><span>:</span><select name="${prefix}_minute" required aria-label="${label} — الدقائق">${minutes}</select><select name="${prefix}_period" required aria-label="${label} — الفترة"><option value="am" ${period==='am'?'selected':''}>ص / صباحًا</option><option value="pm" ${period==='pm'?'selected':''}>م / مساءً</option></select></div></div>`;}
