  function bindSubrouteTimeSuggestion(form){if(!form||form.dataset.timeSuggestionBound)return;form.dataset.timeSuggestionBound='1';const arrival=form.querySelector('[name="destination_arrival_time"]');const departure=form.querySelector('[name="origin_departure_time"]');if(!arrival||!departure)return;const suggest=()=>{if(form.dataset.departureManual==='1'||!arrival.value)return;const [hour,minute]=arrival.value.split(':').map(Number);if(!Number.isFinite(hour)||!Number.isFinite(minute))return;const date=new Date(2000,0,1,hour,minute+30);departure.value=`${String(date.getHours()).padStart(2,'0')}:${String(date.getMinutes()).padStart(2,'0')}`;};arrival.addEventListener('change',suggest);departure.addEventListener('change',()=>{form.dataset.departureManual='1';});if(!departure.value)suggest();}
