  async function dashboardOperations(host){const {operations}=await operationContext();host.innerHTML=`${dashTitle('ملخص التشغيل','اختر قسمًا مستقلاً لإدارة المدن والشركات والمسارات والباصات والرحلات.')}${stats([{l:'المدن النشطة',v:operations.cities.filter(item=>Number(item.is_active)).length,i:'⌖',c:'#0ea5e9'},{l:'المسارات الرئيسية',v:operations.routes.length,i:'↔',c:'#10b981'},{l:'المسارات الفرعية',v:operations.subroutes.length,i:'⌘',c:'#8b5cf6'},{l:'الرحلات',v:operations.trips.length,i:'◷',c:'#f59e0b'}])}<div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(220px,1fr));margin-top:18px">${[['cities','المدن','إضافة المدن وتفعيلها أو إيقافها','⌖'],['companies','الشركات','إضافة شركة وعرض بياناتها','◉'],['routes','المسارات الرئيسية','ربط عدة مسارات فرعية مرتبة','↔'],['route_stops','المسارات الفرعية','تحديد المدينة من وإلى والسعر والعملة','⌘'],['buses','الباصات','إضافة الباصات ومخطط المقاعد','🚌'],['trips','الرحلات','إنشاء الرحلات من مسار وباص','◷']].map(([id,title,text,icon])=>`<section class="panel"><div class="panel-body"><div class="template-activity-row"><span class="template-activity-dot">${icon}</span><div><b>${title}</b><small>${text}</small></div></div><button class="btn btn-primary" style="width:100%;margin-top:16px" data-dash="${id}">فتح القسم</button></div></section>`).join('')}</div>`;$$('[data-dash]',host).forEach(button=>button.addEventListener('click',()=>loadDashboardPage(button.dataset.dash)));}
