  async function dashboardContactMessages(host){
    const {items} = await api('admin/contact-messages');
    const labels = {new:'تم الإرسال', in_progress:'قيد المتابعة', resolved:'تمت المعالجة', failed:'فشل', cancelled:'ملغي'};
    const tone = {new:'confirmed', in_progress:'pending', resolved:'active', failed:'cancelled', cancelled:'cancelled'};
    let activeStatus='all', query='';
    const render=()=>{const filtered=items.filter(item=>(activeStatus==='all'||item.status===activeStatus)&&(!query||[item.full_name,item.phone,item.email,item.subject,item.message].join(' ').toLocaleLowerCase().includes(query.toLocaleLowerCase())));host.innerHTML=`${dashTitle('رسائل اتصل بنا','راجع الرسائل الواردة، ابحث فيها، ثم حدّث حالتها من مكان مستقل.')}<section class="panel contact-messages-panel"><div class="panel-head"><div><h3>الرسائل الواردة (${filtered.length} من ${items.length})</h3><span class="muted">اختر تبويب الحالة أو اكتب كلمة للبحث.</span></div><label class="contact-message-filter"><span>⌕</span><input id="contact-message-query" type="search" placeholder="ابحث بالاسم أو الموضوع أو الهاتف" value="${esc(query)}"></label></div><div class="panel-body"><div class="contact-message-tabs"><button type="button" class="contact-message-tab ${activeStatus==='all'?'active':''}" data-message-status="all">الكل <b>${items.length}</b></button>${Object.entries(labels).map(([value,label])=>`<button type="button" class="contact-message-tab ${activeStatus===value?'active':''}" data-message-status="${value}">${label} <b>${items.filter(item=>item.status===value).length}</b></button>`).join('')}</div><div class="table-scroll"><table class="data-table contact-messages-table"><thead><tr><th>التاريخ</th><th>الاسم</th><th>الهاتف</th><th>البريد</th><th>الموضوع</th><th>المحتوى</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody>${filtered.length ? filtered.map((item) => `<tr><td>${dateTime(item.created_at)}</td><td>${esc(item.full_name)}</td><td dir="ltr">${esc(item.phone)}</td><td dir="ltr">${esc(item.email)}</td><td>${esc(item.subject)}</td><td class="contact-message-preview">${esc(item.message)}</td><td><span class="status ${tone[item.status] || 'active'}">${esc(labels[item.status] || item.status)}</span></td><td><div class="table-actions"><button class="btn btn-outline btn-sm" data-contact-message-view="${item.id}">عرض</button><button class="btn btn-outline btn-sm" data-contact-message-status="${item.id}">الحالة</button></div></td></tr>`).join('') : `<tr><td colspan="8">${empty('لا توجد رسائل تطابق الاختيار الحالي.')}</td></tr>`}</tbody></table></div></div></section>`;bindContactMessageActions(host,items,labels);$('#contact-message-query',host)?.addEventListener('input',event=>{query=event.currentTarget.value;render();});$$('[data-message-status]',host).forEach(button=>button.addEventListener('click',()=>{activeStatus=button.dataset.messageStatus;render();}));};
    const bindContactMessageActions=(target,allItems,statusLabels)=>{const find=(id)=>allItems.find(entry=>Number(entry.id)===Number(id));$$('[data-contact-message-view]',target).forEach(button=>button.addEventListener('click',()=>{const item=find(button.dataset.contactMessageView);if(!item)return;const layer=modal(`<h3>${esc(item.subject||'رسالة من الموقع')}</h3><div class="message-detail-grid"><div><span>الاسم</span><b>${esc(item.full_name)}</b></div><div><span>الهاتف</span><b dir="ltr">${esc(item.phone)}</b></div><div><span>البريد</span><b dir="ltr">${esc(item.email)}</b></div><div><span>التاريخ</span><b>${dateTime(item.created_at)}</b></div></div><div class="contact-message-full"><b>المحتوى</b><p>${esc(item.message)}</p></div><button class="btn btn-outline" type="button" data-modal-close>إغلاق</button>`,'contact-message-detail-dialog');$('[data-modal-close]',layer)?.addEventListener('click',closeModal); }));$$('[data-contact-message-status]',target).forEach(button=>button.addEventListener('click',()=>{const item=find(button.dataset.contactMessageStatus);if(!item)return;const layer=modal(`<h3>تغيير حالة رسالة التواصل</h3><p><b>${esc(item.full_name)}</b> — ${esc(item.subject)}</p><form id="contact-message-status-form"><select name="status" class="field-input">${Object.entries(statusLabels).map(([value,label])=>`<option value="${value}" ${item.status===value?'selected':''}>${label}</option>`).join('')}</select><div class="modal-actions"><button class="btn btn-primary" type="submit">حفظ الحالة</button><button class="btn btn-outline" type="button" data-modal-close>إلغاء</button></div></form>`,'contact-message-status-dialog');$('[data-modal-close]',layer)?.addEventListener('click',closeModal);$('#contact-message-status-form',layer)?.addEventListener('submit',async event=>{event.preventDefault();try{await api(`admin/contact-messages/${item.id}/status`,{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(event.currentTarget)))});closeModal();showToast('تم تحديث حالة رسالة التواصل.','success');dashboardContactMessages(target);}catch(error){showToast(error.message,'error');}});}));};
    render();
  }
