    const financialHeaders=report.report.can_view_financials?'<th>تكلفة الشركة</th><th>مستحق الشركة</th><th>عمولة المنصة</th>':'';const financialCells=(item)=>report.report.can_view_financials?`<td>${money(item.confirmed_company_cost,item.currency_symbol)}</td><td>${money(item.confirmed_company_payable,item.currency_symbol)}</td><td>${money(item.confirmed_platform_commission,item.currency_symbol)}</td>`:'';const columnCount=report.report.can_view_financials?9:6;const comparison=report.report.monthly_comparison||{};const comparisonTrend=Number(comparison.percentage||0);const comparisonPanel=`<section class="dashboard-report-summary report-comparison"><div class="info-box report-info-box report-info-current"><span class="info-box-icon bg-info"><i class="bi bi-calendar-check" aria-hidden="true"></i></span><div class="info-box-content"><span class="info-box-text">حجوزات الشهر الحالي</span><span class="info-box-number">${comparison.current_bookings||0}</span><span class="progress-description">${comparison.current_month||'هذا الشهر'} · مؤكدة: ${comparison.current_confirmed||0}</span></div></div><div class="info-box report-info-box report-info-previous"><span class="info-box-icon bg-secondary"><i class="bi bi-calendar3" aria-hidden="true"></i></span><div class="info-box-content"><span class="info-box-text">حجوزات الشهر السابق</span><span class="info-box-number">${comparison.previous_bookings||0}</span><span class="progress-description">${comparison.previous_month||'الشهر السابق'} · مؤكدة: ${comparison.previous_confirmed||0}</span></div></div><div class="info-box report-info-box ${comparisonTrend>0?'bg-success':comparisonTrend<0?'bg-danger':'bg-secondary'}"><span class="info-box-icon"><i class="bi bi-graph-up-arrow" aria-hidden="true"></i></span><div class="info-box-content"><span class="info-box-text">التغير الشهري</span><span class="info-box-number">${comparisonTrend>0?'+':''}${comparisonTrend}%</span><span class="progress-description">${comparisonTrend>0?'ارتفاع':comparisonTrend<0?'انخفاض':'بدون تغير'} مقارنة بالشهر السابق</span></div></div></section>`;
    host.innerHTML=`${dashTitle('التقارير الأساسية','صفِّ البيانات حسب الموقع والشركة والوكيل والرحلة والفترة والعملة.')}${comparisonPanel}<section class="panel" style="margin-bottom:18px"><div class="panel-body"><form id="report-filter" class="form-grid"><div class="field"><label>من تاريخ</label><input type="date" name="start_date" value="${esc(filters.start_date||'')}"></div><div class="field"><label>إلى تاريخ</label><input type="date" name="end_date" value="${esc(filters.end_date||'')}"></div><div class="field"><label>العملة</label><select name="currency_id"><option value="">كل العملات</option>${currencies.items.map(c=>`<option value="${c.id}" ${String(filters.currency_id)===String(c.id)?'selected':''}>${esc(c.code)} — ${esc(c.name_ar)}</option>`).join('')}</select></div><div class="field"><label>الدولة</label><select name="country_id"><option value="">كل الدول</option>${countries.items.map(c=>`<option value="${c.id}" ${String(filters.country_id)===String(c.id)?'selected':''}>${esc(c.name_ar)}</option>`).join('')}</select></div><div class="field"><label>الشركة</label><select name="company_id"><option value="">كل الشركات</option>${companies.items.map(c=>`<option value="${c.id}" ${String(filters.company_id)===String(c.id)?'selected':''}>${esc(c.trade_name)}</option>`).join('')}</select></div><div class="field"><label>معرف الوكيل</label><input name="agent_id" type="number" min="1" value="${esc(filters.agent_id||'')}" placeholder="اختياري"></div><div class="field"><label>معرف الرحلة</label><input name="trip_id" type="number" min="1" value="${esc(filters.trip_id||'')}" placeholder="اختياري"></div><div class="field"><label>&nbsp;</label><button class="btn btn-primary" type="submit">تطبيق التصفية</button></div></form></div></section><section class="panel"><div class="panel-body"><div class="table-scroll"><table class="data-table"><thead><tr><th>العملة</th><th>إجمالي الحجوزات</th><th>قيد الانتظار</th><th>المؤكدة</th><th>المبيعات المؤكدة</th><th>العمولات</th>${financialHeaders}</tr></thead><tbody>${report.report.by_currency.map(i=>`<tr><td>${esc(i.currency_code)}</td><td>${i.total_bookings}</td><td>${i.pending_bookings}</td><td>${i.confirmed_bookings}</td><td>${money(i.confirmed_sales,i.currency_symbol)}</td><td>${money(i.commissions,i.currency_symbol)}</td>${financialCells(i)}</tr>`).join('')||`<tr><td colspan="${columnCount}">${empty('لا توجد بيانات للفلاتر الحالية.')}</td></tr>`}</tbody></table></div></div></section>`;
